1	import Foundation
2	
3	@Observable @MainActor
4	final class HistoryStore {
5	    private static let maxEntries = 1_000
6	
7	    private let userDefaults: UserDefaults
8	    private let key: String
9	
10	    private(set) var entries: [HistoryEntry] = []
11	
12	    init(userDefaults: UserDefaults = .standard, key: String = "HistoryEntries") {
13	        self.userDefaults = userDefaults
14	        self.key = key
15	        load()
16	    }
17	
18	    func recordVisit(urlString: String, title: String, visitedAt: Date = Date()) {
19	        guard let normalized = normalizedHTTPURLString(urlString) else {
20	            return
21	        }
22	
23	        let storedTitle = displayTitle(for: normalized, title: title)
24	
25	        if entries.first?.urlString == normalized {
26	            entries[0].title = storedTitle
27	            entries[0].visitedAt = visitedAt
28	        } else {
29	            entries.insert(
30	                HistoryEntry(urlString: normalized, title: storedTitle, visitedAt: visitedAt),
31	                at: 0
32	            )
33	
34	            if entries.count > Self.maxEntries {
35	                entries.removeLast(entries.count - Self.maxEntries)
36	            }
37	        }
38	
39	        persist()
40	    }
41	
42	    func updateTitle(for urlString: String, title: String) {
43	        guard
44	            let normalized = normalizedHTTPURLString(urlString),
45	            let index = entries.firstIndex(where: { $0.urlString == normalized })
46	        else {
47	            return
48	        }
49	
50	        let storedTitle = displayTitle(for: normalized, title: title)
51	        guard entries[index].title != storedTitle else {
52	            return
53	        }
54	
55	        entries[index].title = storedTitle
56	        persist()
57	    }
58	
59	    func clear() {
60	        entries.removeAll()
61	        persist()
62	    }
63	
64	    private func load() {
65	        guard let data = userDefaults.data(forKey: key) else {
66	            return
67	        }
68	
69	        do {
70	            entries = try JSONDecoder().decode([HistoryEntry].self, from: data)
71	        } catch {
72	            entries = []
73	        }
74	    }
75	
76	    private func persist() {
77	        do {
78	            let data = try JSONEncoder().encode(entries)
79	            userDefaults.set(data, forKey: key)
80	        } catch {
81	            userDefaults.removeObject(forKey: key)
82	        }
83	    }
84	
85	    private func normalizedHTTPURLString(_ rawValue: String) -> String? {
86	        let trimmed = rawValue.trimmingCharacters(in: .whitespacesAndNewlines)
87	        guard
88	            trimmed.isEmpty == false,
